dat_es &lt;- readRDS(here::here("Rdata", "effect_sizes", "proceed_lnm_safe.rds"))
cat("Total contrasts:", nrow(dat_es), "\n")


Total contrasts: 7237 




Code
# build_or_read_phylogeny() returns list(A = ..., name_map = ...)
# It uses prepR4pcm for name normalisation + 4-stage reconciliation before rotl.
phylo_out &lt;- tryCatch({
  A_path       &lt;- here::here("Rdata", "phylogeny", "proceed_A_matrix.rds")
  name_map_path &lt;- here::here("Rdata", "phylogeny", "proceed_name_map.rds")

  if (file.exists(A_path) && file.exists(name_map_path)) {
    list(A        = readRDS(A_path),
         name_map = readRDS(name_map_path))
  } else {
    message("No cached phylogeny — building via prepR4pcm + rotl ...")
    build_or_read_phylogeny(
      species_vec = unique(as.character(dat_es$sp_ncbi)),
      recompute   = FALSE
    )
  }
}, error = function(e) {
  message("Phylogeny load/build failed: ", conditionMessage(e))
  NULL
})

A_full   &lt;- phylo_out$A
name_map &lt;- phylo_out$name_map

if (!is.null(A_full)) {
  cat("Phylogenetic matrix:", nrow(A_full), "×", ncol(A_full), "\n")
} else {
  message("Phylogenetic matrix unavailable — models will omit the phylogenetic term.")
}


Phylogenetic matrix: 265 &lt;U+00D7&gt; 265 




Code
# Apply the prepR4pcm name map to dat_es ONCE here, adding sp_ncbi_canonical.
# prepare_phylo_and_data() will use this column to match rows to A.
# Rows whose sp_ncbi had no canonical match get NA in sp_ncbi_canonical and
# are excluded from the complete primary-model dataset before fitting.
if (!is.null(name_map)) {
  dat_es &lt;- apply_phylo_name_map(dat_es, name_map)
  n_resolved &lt;- sum(!is.na(dat_es$sp_ncbi_canonical))
  n_na_orig  &lt;- sum(is.na(dat_es$sp_ncbi) | dat_es$sp_ncbi == "")
  n_unresolved &lt;- sum(
    !is.na(dat_es$sp_ncbi) & dat_es$sp_ncbi != "" &
    is.na(dat_es$sp_ncbi_canonical)
  )
  cat("sp_ncbi_canonical coverage:\n")
  cat("  Resolved to canonical name :", n_resolved, "\n")
  cat("  Original sp_ncbi was NA/blank:", n_na_orig, "\n")
  cat("  Named but unresolved        :", n_unresolved, "\n")
} else {
  # No name map — fall back to using sp_ncbi directly
  dat_es$sp_ncbi_canonical &lt;- dat_es$sp_ncbi
  message("No name map available; using sp_ncbi as-is for phylogeny matching.")
}


sp_ncbi_canonical coverage:
  Resolved to canonical name : 7186 
  Original sp_ncbi was NA/blank: 0 
  Named but unresolved        : 51

8.4 Verify moderators exist in the data


Code
grid_status &lt;- moderator_grid |&gt;
  dplyr::mutate(
    in_data = moderator %in% names(dat_es),
    n_nonmissing = purrr::map_int(moderator, function(m) {
      if (m %in% names(dat_es)) sum(!is.na(dat_es[[m]])) else 0L
    })
  )

grid_status







The availability table is evaluated before phylogenetic name matching: all 7,237 eligible contrasts have both elapsed years and elapsed generations because known generation time is part of the inclusion filter. The fitted-model status table below reports the analysis sample after matching to the phylogenetic covariance matrix. Consequently, the elapsed-years and elapsed-generations models share the maximum fitted sample size (7,186 contrasts); the 51 unmatched contrasts are excluded from every phylogeny-adjusted primary model.

8.8 Convergence overview


Code
model_status |&gt;
  dplyr::filter(status == "fitted") |&gt;
  dplyr::select(model_id, moderator, max_rhat, min_bulk_ess, n_divergent) |&gt;
  dplyr::mutate(
    rhat_ok = dplyr::if_else(max_rhat &lt;= 1.01, "ok", "warn"),
    ess_ok  = dplyr::if_else(min_bulk_ess &gt;= 400, "ok", "warn"),
    div_ok  = dplyr::if_else(n_divergent &lt; 10, "ok", "warn")
  )
